{
  "items": [
    {
      "name": "MvPowerSeries.le_weightedOrder",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (w : σ → ℕ) {f : MvPowerSeries σ R} {n : ℕ∞},\n  (∀ (d : σ →₀ ℕ), ↑((Finsupp.weight w) d) < n → (MvPowerSeries.coeff d) f = 0) → n ≤ MvPowerSeries.weightedOrder w f"
    },
    {
      "name": "MvPowerSeries.nat_le_weightedOrder",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (w : σ → ℕ) {f : MvPowerSeries σ R} {n : ℕ},\n  (∀ (d : σ →₀ ℕ), (Finsupp.weight w) d < n → (MvPowerSeries.coeff d) f = 0) → ↑n ≤ MvPowerSeries.weightedOrder w f"
    },
    {
      "name": "MvPolynomial.weightedHomogeneousComponent_eq_zero_of_notMem",
      "module_name": "Mathlib.RingTheory.MvPolynomial.WeightedHomogeneous",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {M : Type u_2} [inst : CommSemiring R] {σ : Type u_3} (w : σ → M) [inst_1 : AddCommMonoid M]\n  [inst_2 : DecidableEq M] (φ : MvPolynomial σ R),\n  ∀ i ∉ Finset.image (⇑(Finsupp.weight w)) φ.support, (MvPolynomial.weightedHomogeneousComponent w i) φ = 0"
    },
    {
      "name": "MvPolynomial.coeff_weightedHomogeneousComponent",
      "module_name": "Mathlib.RingTheory.MvPolynomial.WeightedHomogeneous",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {M : Type u_2} [inst : CommSemiring R] {σ : Type u_3} [inst_1 : AddCommMonoid M] {w : σ → M} (n : M)\n  (φ : MvPolynomial σ R) [inst_2 : DecidableEq M] (d : σ →₀ ℕ),\n  MvPolynomial.coeff d ((MvPolynomial.weightedHomogeneousComponent w n) φ) =\n    if (Finsupp.weight w) d = n then MvPolynomial.coeff d φ else 0"
    },
    {
      "name": "MvPolynomial.weightedHomogeneousComponent_eq_zero'",
      "module_name": "Mathlib.RingTheory.MvPolynomial.WeightedHomogeneous",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {M : Type u_2} [inst : CommSemiring R] {σ : Type u_3} [inst_1 : AddCommMonoid M] {w : σ → M} (n : M)\n  (φ : MvPolynomial σ R),\n  (∀ d ∈ φ.support, (Finsupp.weight w) d ≠ n) → (MvPolynomial.weightedHomogeneousComponent w n) φ = 0"
    }
  ]
}
